// src/engine/core/rng.ts
export interface RngState { readonly s: number; readonly seed: Seed; readonly label: string; }

export function createRng(seed: Seed, label = 'root'): RngState { return { s: seed >>> 0, seed, label }; }

// Pure: returns advanced state + value. Never mutates input.
export function nextU32(r: RngState): readonly [RngState, number] {
  const s = (r.s + 0x6d2b79f5) >>> 0;
  let t = s; t = Math.imul(t ^ (t >>> 15), t | 1);
  t ^= t + Math.imul(t ^ (t >>> 7), t | 61);
  return [{ ...r, s }, (t ^ (t >>> 14)) >>> 0];
}

// Independent child stream WITHOUT consuming parent (splitmix64-on-uint32 of seed^hash(salt)).
export function forkRng(parent: RngState, salt: string | number): RngState { /* ... */ return parent; }

// Ergonomic, still pure: a cursor object the caller threads explicitly. No hidden global state.
export interface Rng {
  fork(salt: string | number): Rng;
  float(): number; range(lo: number, hi: number): number; int(lo: number, hi: number): number;
  chance(p: number): boolean; pick<T>(a: readonly T[]): T;
  readonly state: RngState; // serialize the cursor back into GameState.rngStreams
}

// src/engine/core/types.ts
export type TickGranularity = 'day' | 'week' | 'month';
export interface Calendar {
  readonly dayIndex: DayIndex;       // THE authoritative time value
  readonly year: number; readonly month: number; readonly day: number; readonly weekday: number; // derived caches
  readonly tickGranularity: TickGranularity;
  readonly tickCount: number;        // monotonic; RNG salt + event tiebreak
}

// src/engine/core/types.ts
export interface GameState {
  readonly schemaVersion: number;
  readonly gameId: string;
  readonly rootSeed: Seed;
  readonly mode: 'campaign' | 'governing' | 'sandbox';
  readonly meta: { readonly revision: number; readonly rulesetId: string; readonly scenarioId: string; readonly playerEntityId: EntityId | null; readonly contentHash: string; readonly difficulty: 'easy'|'normal'|'hard'|'brutal' };
  readonly calendar: Calendar;
  readonly rngStreams: Readonly<Record<string, RngState>>; // long-lived: events, graphNoise, ai, polling
  readonly graph: GraphState;
  readonly eventQueue: EventQueueState;
  readonly ledger: readonly ScheduledEffect[]; // the ONE effects ledger campaign+governing both feed
  readonly entities: EntityStores;
  readonly history: readonly TickDigest[]; // ring buffer
}
// Each subsystem owns a normalized slice keyed by EntityId. Records, never Map/Set.
export interface EntityStores {
  readonly electoral: { jurisdictions: Record<string, Jurisdiction>; offices: Record<string, OfficeDefinition>; seats: Record<string, Seat>; officeholders: Record<string, Officeholder>; elections: Record<string, ElectionInstance>; candidacies: Record<string, Candidacy>; };
  readonly electorate: Record<string, ElectorateState>; // keyed by jurisdictionId
  readonly campaigns: Record<string, CampaignState>;
  readonly gov: GovState; // bills, legislators, committees, processes, deals
}

// src/engine/core/types.ts
export type SimNodeKind = 'simValue' | 'policy' | 'situation' | 'groupAttr' | 'input';
export type TransferKind = 'linear' | 'multiplier' | 'sigmoid' | 'step' | 'inverse';
export interface SimNode { readonly id: string; readonly kind: SimNodeKind; readonly min: number; readonly max: number; readonly baseValue: number; readonly inertia: Unit01; readonly volatility: number; readonly activeThreshold: number | null; readonly tags: readonly string[]; }
export interface SimEdge { readonly id: string; readonly from: string; readonly to: string; readonly weight: Signed1; readonly transfer: TransferKind; readonly lag: number; readonly curve: number; }
export interface GraphState { readonly values: Record<string, number>; readonly targets: Record<string, number>; readonly lagBuffers: Record<string, readonly number[]>; }

// src/engine/core/ledger.ts
export type EffectTarget =
  | { readonly type: 'simValue'; readonly valueId: string }
  | { readonly type: 'groupHappiness'; readonly groupId: string }
  | { readonly type: 'situation'; readonly situationId: string; readonly op: 'trigger' | 'clear' | 'intensify' }
  | { readonly type: 'economy'; readonly indicatorId: string }
  | { readonly type: 'electorate'; readonly channel: 'nameRecognition'|'favorability'|'turnoutPropensity'|'persuasion'|'opponentFavorability'; readonly jurisdictionId: string; readonly segmentWeights: Readonly<Record<string, number>>; readonly issueId?: string; readonly tone?: Signed1 };
export interface ScheduledEffect {
  readonly id: string;
  readonly target: EffectTarget;
  readonly op: 'add' | 'mul' | 'set' | 'addPercentOfBase';
  readonly magnitude: number;
  readonly enactedDay: DayIndex;
  readonly rampStartTicks: number; readonly rampDurationTicks: number; readonly decayHalfLifeTicks: number | null; readonly sunsetDay: DayIndex | null;
  readonly attributionActorId: EntityId | null; // legislator/exec/candidate credited or blamed
  readonly sourceSubsystem: 'campaign' | 'governing' | 'event';
  readonly reversible: boolean; // EOs true; statutes false
}
export function appliedMagnitudeAt(e: ScheduledEffect, day: DayIndex): number { return 0; /* ramp*decay*sunset */ }

// src/engine/core/types.ts
export interface Action<T extends string = string, P = unknown> { readonly type: T; readonly payload: P; readonly meta?: { readonly source: 'player'|'event'|'ai'|'system'; readonly tick: number }; }
export interface ReducerCtx { readonly registry: ContentRegistry; rngFork(salt: string | number): Rng; readonly nowDay: DayIndex; }
export interface ActionResult { readonly ok: boolean; readonly errors: readonly { code: string; message: string; field?: string }[]; readonly cost: { cash?: Cents; actionPoints?: number; politicalCapital?: number }; readonly previewDelta?: Record<string, number>; readonly revisionAfter: number; }
export type ApplyAction = (state: GameState, action: Action, ctx: ReducerCtx) => GameState;
export type ValidateAction = (state: GameState, action: Action) => ActionResult;

// src/engine/electorate/types.ts
export interface CandidateProfile { readonly candidateId: EntityId; readonly partyId: string; readonly positions: Readonly<Record<string, Signed1>>; readonly valence: Unit01; readonly incumbent: boolean; readonly identityTags: Readonly<Record<string, string>>; readonly scandalLoad: Unit01; }
export interface AllocationResult { readonly winnerIds: readonly EntityId[]; readonly votesByCandidate: Readonly<Record<string, number>>; readonly turnout: number; readonly margin: number; readonly rounds?: readonly Readonly<Record<string, number>>[]; readonly status: 'resolved'|'runoff_required'|'contingent_election'|'tie_unresolved'; }
// Pure, RNG-free. Same inputs => identical output (determinism contract).
export type EvaluateElectorate = (e: ElectorateState, candidates: readonly CandidateProfile[], ctx: { phase: 'primary'|'general'; partyScope?: string }) => AllocationResult;
// The narrow read model the CAMPAIGN engine is allowed to see (no write access).
export interface ElectorateReadModel { segmentSize(jid: string, segmentId: string): number; leanSupport(jid: string, segmentId: string, candidateId: EntityId): number; latestPoll(jid: string): Poll | null; }
